// flashcard drill — JAH Radio Alphabet and Procedure Database (jahdb demo program)
var ITEMS=[["Alpha","The letter A in the NATO phonetic alphabet."], ["Bravo","The letter B."], ["Charlie","The letter C."], ["Delta","The letter D."], ["Echo","The letter E."], ["Foxtrot","The letter F."], ["Golf","The letter G."], ["Hotel","The letter H."], ["India","The letter I."], ["Juliett","The letter J."], ["Kilo","The letter K."], ["Lima","The letter L."], ["Mike","The letter M."], ["November","The letter N."], ["Oscar","The letter O."], ["Papa","The letter P."], ["Quebec","The letter Q."], ["Romeo","The letter R."], ["Sierra","The letter S."], ["Tango","The letter T."], ["Uniform","The letter U."], ["Victor","The letter V."], ["Whiskey","The letter W."], ["X-ray","The letter X."], ["Yankee","The letter Y."], ["Zulu","The letter Z."], ["Affirmative","Yes; permission granted or statement confirmed."], ["Negative","No; not confirmed."], ["Roger","Message received and understood."], ["Wilco","Will comply with instructions."], ["Say again","Repeat your last transmission."], ["Over","My transmission ended; a reply is expected."], ["Out","My transmission ended; no reply expected."], ["Break","Pause to separate message parts."], ["Standby","Wait; I will call you back."], ["Copy","I heard and understood."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
